#define PI 3.1415
#define MAX_ITER 8
#define NUM_BUCKETS 10.

mat2 rotationMatrix(float angle)
{
    float sine = sin(angle), cosine = cos(angle);
    return mat2( cosine, -sine, 
                 sine,    cosine );
}

float rand(vec2 x) {
    return fract(sin(dot(x,
                         vec2(12.9898,78.233)))*
        43758.5453123);
}

vec2 rand2( vec2 p ) {
    return fract(sin(vec2(dot(p,vec2(127.1,311.7)),dot(p,vec2(269.5,183.3))))*43758.5453);
}



float blink(vec2 seed, float time){
    float cyclic_time = mod(time, NUM_BUCKETS);
    float bucket = rand2(seed).x*NUM_BUCKETS;
    float sq = cyclic_time - bucket - 0.5;
    float exponent = -4.*3.1415*sq*sq;
    return 4./(1.0 - exp(exponent));
}

float eye(vec2 uv, float size, vec2 look_dir) {
    float ball = smoothstep(0.0, 0.05, cos(uv.x * PI) - size * uv.y) *
                 smoothstep(0.0, 0.05, cos(uv.x * PI) + size * uv.y);

    // Smooth the edge of the eye
    float iris = smoothstep(0.2, 0.205, length(uv-look_dir*0.02));
    float pupil =  smoothstep(0.055, 0.050, length(uv-look_dir*0.022));
    return (pupil+iris) * (ball);
} 

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    // Normalized pixel coordinates (from 0 to 1)
    vec2 uv = fragCoord/iResolution.xy;
    uv -= vec2(0.5);
    uv.x *= iResolution.x / iResolution.y; // Fix aspect ratio
    uv*= 1.;
    vec2 pos = 3.*(vec2(2.*sin(2.*iTime),cos(5.*iTime)));

    float val = eye(uv, blink(vec2(0.0),iTime),pos);
    float sign_factor = -1.;
    for(int i = 0; i<MAX_ITER; i++){
        uv = 1.1*uv*rotationMatrix(0.1*sign_factor*iTime);
        vec2 st = uv;
        vec2 id = floor(st);
        st.x += sign(sign_factor)*0.1*(mod(id.y,2.0) == 0. ? iTime : -iTime);
        id = floor(st);
        st = fract(st) - 0.5;
        pos = 3.*(vec2(2.*sin(2.*iTime+id.x+float(i)),cos(5.*iTime+id.y+float(i))));
        val = mix(sign_factor*eye(st, blink(id+float(i),iTime),pos),val,0.8);
        sign_factor *= -1.1+0.1*sin(0.1*iTime);
    }

    // Time varying pixel color
    vec3 col = vec3(val);

    // Output to screen
    fragColor = vec4(col,1.0);
}
